-- Do not edit: change the spec in model/ and regenerate.

CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.submission_metrics
COMMENT 'Reinsurance submission funnel KPIs: volumes and requested capacity by status, form and year. Amounts are in original submission currency; group by or filter on currency_code before summing money. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_reinsurance.submission

joins:
  - name: submission_status
    source: lr_serverless_aws_us_catalog.bricksurance_reference.submission_status
    on: source.submission_status_code = submission_status.submission_status_code
  - name: line_of_business
    source: lr_serverless_aws_us_catalog.bricksurance_reference.line_of_business
    on: source.line_of_business_code = line_of_business.line_of_business_code

dimensions:
  - name: underwriting_year
    expr: underwriting_year
  - name: submission_status
    expr: submission_status.label
  - name: treaty_type_code
    expr: treaty_type_code
  - name: line_of_business
    expr: line_of_business.label
  - name: line_of_business_code
    expr: source.line_of_business_code
  - name: currency_code
    expr: currency_code

measures:
  - name: submission_count
    expr: COUNT(DISTINCT submission_id)
  - name: bound_count
    expr: COUNT(DISTINCT CASE WHEN submission_status_code = 'BOUND' THEN submission_id END)
  - name: bind_ratio
    expr: COUNT(DISTINCT CASE WHEN submission_status_code = 'BOUND' THEN submission_id END) / NULLIF(COUNT(DISTINCT submission_id), 0)
  - name: requested_limit_total
    expr: SUM(requested_limit)
$$;
